"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["8265"],{52520(i){i.exports=JSON.parse('{"tag":{"label":"Chinchillas","permalink":"/docs/tags/chinchillas","allTagsPath":"/docs/tags","count":31,"items":[{"id":"general-care/health-and-medical/skin-issues","title":"A Guide to Common Skin Issues in Small Pets","description":"A comprehensive guide to identifying, preventing, and treating common skin problems in small exotic pets, including urine scald, mites, ringworm, and bacterial infections, with species-specific advice.","permalink":"/docs/general-care/health-and-medical/skin-issues"},{"id":"Chinchillas/care-and-husbandry/nutrition","title":"Chinchilla Nutrition and Diet","description":"A chinchilla\'s digestive system is incredibly sensitive and has evolved to process a diet of sparse, high-fiber vegetation. Providing a species-appropriate diet is the single most important thing you can do to ensure your chinchilla lives a long, healthy life. This guide covers the essential components of a healthy chinchilla diet.","permalink":"/docs/Chinchillas/care-and-husbandry/nutrition"},{"id":"Chinchillas/care-and-husbandry/wheels-vs-saucers","title":"Chinchilla Wheels and Saucers: What You Need to Know","description":"A guide to choosing a safe wheel or saucer for chinchillas \u2014 covering minimum size recommendations, the flying saucer debate, overheating risks, and what features to look for.","permalink":"/docs/Chinchillas/care-and-husbandry/wheels-vs-saucers"},{"id":"Chinchillas/health/common-health-issues","title":"Common Health Issues in Chinchillas","description":"An overview of the most common health issues affecting pet chinchillas, including dental disease, bloat, ringworm, and heat stroke, with a focus on prevention and recognizing early warning signs.","permalink":"/docs/Chinchillas/health/common-health-issues"},{"id":"general-care/safety/dangerous-plants","title":"Dangerous Plants for Small Pets: A Regional Guide","description":"Global dangerous plants infographic","permalink":"/docs/general-care/safety/dangerous-plants"},{"id":"Chinchillas/health/dental-health","title":"Dental Health in Chinchillas","description":"A comprehensive guide to dental disease in chinchillas, covering the causes of malocclusion, recognizing the signs of dental problems, diagnosis, treatment options, and the critical role of a high-hay diet in prevention.","permalink":"/docs/Chinchillas/health/dental-health"},{"id":"Chinchillas/health/diabetes-in-chinchillas","title":"Diabetes in Chinchillas","description":"Learn about the causes, symptoms, diagnosis, and management of diabetes mellitus in chinchillas, including diet and lifestyle changes.","permalink":"/docs/Chinchillas/health/diabetes-in-chinchillas"},{"id":"Chinchillas/care-and-husbandry/essential-supplies","title":"Essential Supplies for Pet Chinchillas","description":"A complete checklist of the essential supplies required to create a safe, healthy, and enriching environment for pet chinchillas.","permalink":"/docs/Chinchillas/care-and-husbandry/essential-supplies"},{"id":"Chinchillas/health/eye-and-vision-issues","title":"Eye & Vision Issues in Chinchillas","description":"A guide to common eye and vision issues in chinchillas, including watery eyes (epiphora) as a sign of dental disease, conjunctivitis, and corneal ulcers.","permalink":"/docs/Chinchillas/health/eye-and-vision-issues"},{"id":"Chinchillas/health/gi-health","title":"Gastrointestinal (GI) Health in Chinchillas","description":"An essential guide to gastrointestinal (GI) health in chinchillas, covering their sensitive digestive system, the causes and signs of life-threatening bloat and GI stasis, and the importance of a high-hay diet.","permalink":"/docs/Chinchillas/health/gi-health"},{"id":"Chinchillas/care-and-husbandry/grooming","title":"Grooming Your Pet Chinchilla","description":"A guide to the unique grooming needs of chinchillas, focusing on the importance of dust baths and how to provide them safely.","permalink":"/docs/Chinchillas/care-and-husbandry/grooming"},{"id":"Chinchillas/health/heartdisease","title":"Heart Disease and Heart Failure in Chinchillas","description":"Heart disease and heart failure are relatively uncommon in chinchillas but can still occur, especially as they age or due to certain genetic predispositions. These conditions can be challenging to detect early on, as chinchillas tend to hide their symptoms until the disease has progressed. Understanding the causes, signs, and treatments of heart disease in chinchillas is key to ensuring your pet remains healthy and receives proper care.","permalink":"/docs/Chinchillas/health/heartdisease"},{"id":"Chinchillas/health/heat-stroke-in-chinchillas","title":"Heat Stroke in Chinchillas","description":"Learn how to recognize, prevent, and respond to heat stroke in chinchillas, including emergency first aid and safe temperature ranges.","permalink":"/docs/Chinchillas/health/heat-stroke-in-chinchillas"},{"id":"Chinchillas/health/home-health-care","title":"Home Health Care for Your Chinchilla","description":"Chinchillas are masters at hiding illness, a survival instinct inherited from their wild ancestors. This means that by the time a chinchilla shows obvious signs of being sick, they may have been unwell for some time. Performing regular health checks at home is one of the most effective ways to catch potential problems early. This guide will walk you through how to conduct a gentle, thorough health check for your chinchilla.","permalink":"/docs/Chinchillas/health/home-health-care"},{"id":"Chinchillas/health/introductions-and-bonding","title":"Introducing and Bonding Chinchillas","description":"A step-by-step guide to safely introducing chinchillas and helping them bond, covering quarantine, pairing considerations, introduction methods, body language, and what to do when bonding fails.","permalink":"/docs/Chinchillas/health/introductions-and-bonding"},{"id":"general-care/daily-care/introductions-and-bonding","title":"Introductions and Bonding","description":"How to safely introduce small pets to each other \u2014 covering quarantine, scent swapping, neutral space introductions, and warning signs for all HALT species.","permalink":"/docs/general-care/daily-care/introductions-and-bonding"},{"id":"Chinchillas/getting-started/is-a-chinchilla-right-for-me","title":"Is a Chinchilla Right for Me and My Family?","description":"Chinchillas are extraordinary animals \u2014 soft as velvet, agile as acrobats, and capable of living 20 years or more with excellent care. That extraordinary lifespan is also the most important thing to...","permalink":"/docs/Chinchillas/getting-started/is-a-chinchilla-right-for-me"},{"id":"Chinchillas/breeds-and-genetics/know-your-chinchilla-breeds","title":"Know Your Chinchilla Breeds","description":"An overview of chinchilla species and the wide variety of color mutations found in pet chinchillas.","permalink":"/docs/Chinchillas/breeds-and-genetics/know-your-chinchilla-breeds"},{"id":"Chinchillas/health/parasites","title":"Parasites & Ringworm in Chinchillas","description":"A comprehensive guide to parasites and ringworm in chinchillas, covering fur mites, fleas, lice, Giardia, coccidia, intestinal worms, and the fungal infection ringworm \u2014 with diagnosis, treatment, and prevention guidance.","permalink":"/docs/Chinchillas/health/parasites"},{"id":"Chinchillas/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Chinchilla","description":"Chinchillas are active, athletic animals that need daily out-of-cage time and enrichment. Learn how to safely play with and train your chinchilla.","permalink":"/docs/Chinchillas/care-and-husbandry/playing-and-training"},{"id":"general-care/health-and-medical/pneumonia-in-small-pets","title":"Pneumonia in Small Pets","description":"A general guide to pneumonia in small pets, covering causes, species-specific signs, diagnosis, treatment, and prevention for rabbits, rats, ferrets, chinchillas, hamsters, gerbils, hedgehogs, mice, and degus.","permalink":"/docs/general-care/health-and-medical/pneumonia-in-small-pets"},{"id":"Chinchillas/care-and-husbandry/proper-handling","title":"Proper Handling of Pet Chinchillas","description":"A guide to safely and confidently handling pet chinchillas, with techniques for building trust and correctly picking them up.","permalink":"/docs/Chinchillas/care-and-husbandry/proper-handling"},{"id":"Chinchillas/health/respiratory-issues","title":"Respiratory Issues in Chinchillas","description":"A comprehensive guide to respiratory infections in chinchillas, covering bacterial causes, environmental risk factors, warning signs, diagnosis, treatment, and prevention through good husbandry.","permalink":"/docs/Chinchillas/health/respiratory-issues"},{"id":"general-care/daily-care/safe-treats","title":"Safe Treats for Small Pets","description":"A comprehensive guide to safe and unsafe treats for all small pet species, including rabbits, guinea pigs, rats, hamsters, gerbils, chinchillas, ferrets, hedgehogs, mice, and degus.","permalink":"/docs/general-care/daily-care/safe-treats"},{"id":"Chinchillas/breeds-and-genetics/satin-syndrome","title":"Satin Chinchillas and Satin Syndrome","description":"An overview of the satin gene in chinchillas, how to identify a satin chinchilla, and the serious health condition known as satin syndrome (fibrous osteodystrophy).","permalink":"/docs/Chinchillas/breeds-and-genetics/satin-syndrome"},{"id":"Chinchillas/breeds-and-genetics/sexing-your-chinchilla","title":"Sexing Your Pet Chinchilla","description":"A clear and simple guide to determining the sex of a pet chinchilla by examining the anogenital distance and key anatomical features.","permalink":"/docs/Chinchillas/breeds-and-genetics/sexing-your-chinchilla"},{"id":"general-care/daily-care/outdoor-safety","title":"Taking Your Small Pet Outside Safely","description":"Outdoor safety infographic for small pets","permalink":"/docs/general-care/daily-care/outdoor-safety"},{"id":"Chinchillas/care-and-husbandry/habitat","title":"The Ideal Chinchilla Habitat","description":"<InfographicShare","permalink":"/docs/Chinchillas/care-and-husbandry/habitat"},{"id":"Chinchillas/health/understanding-chinchilla-behavior","title":"Understanding Chinchilla Behavior: A Guide for Owners","description":"Chinchillas are active, curious animals with a surprisingly rich behavioral repertoire. They are crepuscular \u2014 most active at dawn and dusk \u2014 and can live for 15 years or more.","permalink":"/docs/Chinchillas/health/understanding-chinchilla-behavior"},{"id":"Chinchillas/health/understanding-chinchilla-droppings","title":"Understanding Chinchilla Droppings","description":"A complete guide to chinchilla droppings \u2014 what normal poop looks like, what changes in colour, size, shape, or texture mean, cecotropes explained, and when to call the vet.","permalink":"/docs/Chinchillas/health/understanding-chinchilla-droppings"},{"id":"Chinchillas/health/urinary-and-bladder-health","title":"Urinary & Bladder Health in Chinchillas","description":"A comprehensive guide to urinary and bladder health in chinchillas, covering UTIs, bladder sludge, urolithiasis, symptoms, diagnosis, treatment, and prevention.","permalink":"/docs/Chinchillas/health/urinary-and-bladder-health"}],"unlisted":false}}')}}]);